body:
> We could still use Vector with resize, and then get the ptr, and fill it manually, which involve keeping indexes for each one, but it avoids the last copies. This is definitely harder to write and more error prone, so this version is a good trade off.

It is in general a bit faster, but won't be much for a relatively small amount of points, and I guess not worth the effort.

<details>
  <summary>A quick synthetic test</summary>

```c++
	{
		auto t0 = std::chrono::high_resolution_clock::now();
		for (int i = 0; i < 50000; i++) {
			Array a;
			a.push_back(Vector<Vector3>());

			Vector<Vector3> points;
			for (int j = 0; j < 10000; j++) {
				points.push_back(Vector3(j*j*j, j, j*j));
			}
			a[0] = points;
		}	
		auto t1 = std::chrono::high_resolution_clock::now();
		print_line("Vector::push_back ", std::chrono::duration_cast<std::chrono::milliseconds>(t1 - t0).count(), " ms");
	}
	{
		auto t0 = std::chrono::high_resolution_clock::now();
		for (int i = 0; i < 50000; i++) {
			Array a;
			a.push_back(Vector<Vector3>());

			LocalVector<Vector3> points;
			points.reserve(10000);
			for (int j = 0; j < 10000; j++) {
				points.push_back(Vector3(j*j*j, j, j*j));
			}
			a[0] = Vector<Vector3>(points);
		}	
		auto t1 = std::chrono::high_resolution_clock::now();
		print_line("LocalVector::push_back ", std::chrono::duration_cast<std::chrono::milliseconds>(t1 - t0).count(), " ms");
	}
	{
		auto t0 = std::chrono::high_resolution_clock::now();
		for (int i = 0; i < 50000; i++) {
			Array a;
			a.push_back(Vector<Vector3>());

			Vector<Vector3> points;
			points.resize(10000);
			Vector3 *ptr = points.ptrw();
			for (int j = 0; j < 10000; j++) {
				ptr[j] = Vector3(j*j*j, j, j*j);
			}
			a[0] = points;
		}	
		auto t1 = std::chrono::high_resolution_clock::now();
		print_line("Vector::ptrw ", std::chrono::duration_cast<std::chrono::milliseconds>(t1 - t0).count(), " ms");
	}
```

</details>

